window.EW=window.EW||{pages:{}};window.EW.pages["wiki-glossaire"]={"html":"<p>Les termes du lore d'Elderwood.<\/p><ul><li><strong><a href=\"#/p/wiki-principes-fondamentaux--lecho\">Écho<\/a><\/strong> : Aussi appelé magie, l'origine de toute chose.<\/li><li><strong><a href=\"#/p/wiki-principes-fondamentaux--la-resonance\">Résonance<\/a><\/strong> : Réponse propre de chaque être vivant à l'Écho, reposant sur deux prédispositions génétiques : ressentir l'Écho, et le contrôler.<\/li><li><strong><a href=\"#/p/wiki-principes-fondamentaux--le-flux\">Flux<\/a><\/strong> : Énergie née de la rencontre entre l'Écho et la Résonance.<\/li><li><strong><a href=\"#/p/wiki-principes-fondamentaux--les-statuts-magiques\">Sans-Flux<\/a><\/strong> : Humains dont la Résonance est trop faible pour produire un Flux exploitable.<\/li><li><strong><a href=\"#/p/wiki-principes-fondamentaux--les-statuts-magiques\">Dissonant<\/a><\/strong> : Né de parents Sans-Flux mais présentant une des deux prédispositions de la Résonance.<\/li><li><strong><a href=\"#/p/wiki-principes-fondamentaux--le-voile\">Voile<\/a><\/strong> : Phénomène dissimulant un lieu chargé de Flux aux Sans-Flux.<\/li><li><strong><a href=\"#/p/wiki-principes-fondamentaux--le-flux\">Catalyseur<\/a><\/strong> : Objet (baguette, sceptre, bâton, flûte, ou tout autre instrument magique) canalisant le Flux du sorcier.<\/li><li><strong><a href=\"#/p/wiki-les-lieux--la-source\">La Source de Vehr<\/a><\/strong> : Aussi appelée « la Source », bassin d'eau révélant la couleur du Flux de chaque Résonant.<\/li><li><strong>Razorball<\/strong> : Sport international sorcier, aussi appelé « le Raze ».<\/li><\/ul>","toc":[]};
